MAP
    NAME "SS_MAP_DREN_DRENAJE_SECTORES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_drenaje_sectores.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_DRENAJE_UBICACION"
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_drenaje_sector from l_drenaje_sectores using unique id_drenaje_sectores using srid=32614"
        TYPE POLYGON
        LABELITEM "nb_sector"
        CLASS
            NAME "Nombre sector"
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 19
                PARTIALS FALSE
                COLOR 161 102 50
            END	
            STYLE
                WIDTH 8
                OUTLINECOLOR 161 102 50
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP